defmodule Bard.JinjaTest do
  use ExUnit.Case, async: true

  alias Bard.Jinja

  # Expected outputs come from Python's Jinja2 with dbt's settings, generated by
  # test/fixtures/jinja/generate_cases.py. Each case is its own test.
  @cases "test/fixtures/jinja/cases.json" |> File.read!() |> Jason.decode!()

  @globals Map.fetch!(@cases, "_globals")

  for {name, %{"template" => template, "expected" => expected}} <- Map.delete(@cases, "_globals") do
    test "matches Jinja2: #{name}" do
      assert Jinja.render(unquote(template), @globals) == {:ok, unquote(expected)}
    end
  end

  describe "errors name the line" do
    test "unsupported tags" do
      assert {:error, %Jinja.Error{line: 2, reason: {:unsupported_tag, "call"}}} =
               Jinja.render("ok\n{% call m() %}x{% endcall %}", %{})
    end

    test "unclosed blocks and tags" do
      assert {:error, %Jinja.Error{line: 1, reason: :unclosed_block}} =
               Jinja.render("{% if x %}", %{})

      assert {:error, %Jinja.Error{line: 3, reason: :unclosed_tag}} =
               Jinja.render("a\n\n{{ x", %{})
    end

    test "calling something undefined" do
      assert {:error, %Jinja.Error{line: 1, reason: {:undefined_function, "run_query"}}} =
               Jinja.render("{{ run_query('select 1') }}", %{})
    end

    test "mutating a list" do
      assert {:error, %Jinja.Error{reason: {:unsupported_method, "append"}}} =
               Jinja.render("{% set l = [] %}{% do l.append(1) %}", %{})
    end
  end

  describe "Elixir integration" do
    test "functions and objects from Elixir" do
      ref = fn [name], _kwargs ->
        %Jinja.Object{str: ~s("db"."s"."#{name}"), attrs: %{"identifier" => name}}
      end

      assert Jinja.render("{{ ref('orders') }} {{ ref('orders').identifier }}", %{"ref" => ref}) ==
               {:ok, ~s("db"."s"."orders" orders)}
    end

    test "keyword arguments arrive as a map" do
      config = fn [], kwargs -> send(self(), {:config, kwargs}) && "" end

      assert {:ok, ""} =
               Jinja.render("{{ config(materialized='table', tags=['a']) }}", %{
                 "config" => config
               })

      assert_received {:config, %{"materialized" => "table", "tags" => ["a"]}}
    end

    test "macros from a file, called from Elixir, with return()" do
      {:ok, macros} =
        Jinja.macros("""
        {% macro double(x) %}{{ return(x * 2) }}{% endmacro %}
        {% macro greet(name) -%} hi {{ name }} {%- endmacro %}
        """)

      return = fn [value], _ -> throw({:jinja_return, value}) end
      assert Jinja.call(macros["double"], [21], %{}, %{"return" => return}) == {:ok, 42}
      assert Jinja.call(macros["greet"], ["ana"], %{}, %{}) == {:ok, "hi ana"}
    end
  end
end
